    private void btnAddProductActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAddProductActionPerformed
        // TODO add your handling code here:
        String productName = txtProductName.getText().trim();
        String brand = txtBrand.getText().trim();
        String size = txtSize.getText().trim();
        String color = txtColor.getText().trim();
        String priceText = txtPrice.getText().trim();
        String stockText = txtStock.getText().trim();

            if (cmbCategory.getSelectedItem() == null) {
                javax.swing.JOptionPane.showMessageDialog(
                this,
                "Please select a category.",
                "Validation Error",
                javax.swing.JOptionPane.WARNING_MESSAGE
                );
            return;
            }

        String categoryName =
            cmbCategory.getSelectedItem().toString();

        // Validate empty fields
        if (productName.isEmpty()
            || brand.isEmpty()
            || size.isEmpty()
            || color.isEmpty()
            || priceText.isEmpty()
            || stockText.isEmpty()) {

        javax.swing.JOptionPane.showMessageDialog(
                this,
                "Please fill all fields.",
                "Validation Error",
                javax.swing.JOptionPane.WARNING_MESSAGE
        );

        return;
            }

        double price;
        int stock;

        // Convert price and stock
        try {

            price = Double.parseDouble(priceText);
            stock = Integer.parseInt(stockText);

        } catch (NumberFormatException e) {

            javax.swing.JOptionPane.showMessageDialog(
                this,
                "Price must be a number and Stock Quantity must be a whole number.",
                "Invalid Input",
                javax.swing.JOptionPane.ERROR_MESSAGE
        );

        return;
        }

        // Validate price
        if (price < 0) {

            javax.swing.JOptionPane.showMessageDialog(
                this,
                "Price cannot be negative.",
                "Invalid Price",
                javax.swing.JOptionPane.WARNING_MESSAGE
            );

        return;
        }

        // Validate stock
        if (stock < 0) {

            javax.swing.JOptionPane.showMessageDialog(
                this,
                "Stock quantity cannot be negative.",
                "Invalid Stock",
                javax.swing.JOptionPane.WARNING_MESSAGE
            );

        return;
        }

        // Get Category ID
        int categoryID = 0;

        if (categoryName.equals("Casual Wear")) {
        categoryID = 1;

        } else if (categoryName.equals("Formal Wear")) {
        categoryID = 2;

        } else if (categoryName.equals("Sportswear")) {
        categoryID = 3;

        } else if (categoryName.equals("Footwear")) {
        categoryID = 4;

        } else if (categoryName.equals("Accessories")) {
        categoryID = 5;
        }

        // Create Product object
        model.Product product = new model.Product();

        product.setProductName(productName);
        product.setBrand(brand);
        product.setCategoryID(categoryID);
        product.setSize(size);
        product.setColor(color);
        product.setPrice(price);
        product.setStockQuantity(stock);

        // Add product to database
        dao.ProductDAO productDAO = new dao.ProductDAO();

        boolean success =
                productDAO.addProduct(product);

        if (success) {

            javax.swing.JOptionPane.showMessageDialog(
                    this,
                    "Product added successfully!",
                    "Success",
                    javax.swing.JOptionPane.INFORMATION_MESSAGE
            );

        // Clear fields
        txtProductName.setText("");
        txtBrand.setText("");
        txtSize.setText("");
        txtColor.setText("");
        txtPrice.setText("");
        txtStock.setText("");

        cmbCategory.setSelectedIndex(0);

        txtProductName.requestFocus();

        } else {

        javax.swing.JOptionPane.showMessageDialog(
                this,
                "Failed to add product.",
                "Error",
                javax.swing.JOptionPane.ERROR_MESSAGE
        );
        }
    }//GEN-LAST:event_btnAddProductActionPerformed

