    private void loadCategories() {

        dao.CategoryDAO categoryDAO = new dao.CategoryDAO();

        String[] categories = {
        "Casual Wear",
        "Formal Wear",
        "Sportswear",
        "Footwear",
        "Accessories"
        };

        cmbCategory.removeAllItems();

        for (String category : categories) {

        cmbCategory.addItem(category);
        }
    }
